<?php $u=rtrim($_ENV['APP_URL']??'','/'); ?>
<div class="page-head"><div><span class="eyebrow">COORDINACIÓN TICS</span><h1>Ampliaciones de cupos</h1><p>Notificaciones internas y resolución de solicitudes.</p></div></div>
<?php if($flash):?><section class="card"><p><?=htmlspecialchars($flash['message'])?></p></section><?php endif;?>
<section class="card"><div class="table-scroll"><table><thead><tr><th>Sección</th><th>Solicitados</th><th>Estado</th><th>Motivo</th><th>Solicitante</th><th>Fecha</th><th>Acción</th></tr></thead><tbody>
<?php foreach($requests as $r):?><tr><td><?=htmlspecialchars($r['seccion_codigo'])?></td><td><?=(int)$r['cantidad_solicitada']?></td><td><?=htmlspecialchars($r['estado'])?></td><td><?=htmlspecialchars($r['motivo'])?></td><td>#<?=(int)$r['solicitado_por_usuario_id']?></td><td><?=htmlspecialchars($r['solicitado_en'])?></td><td><?php if($r['estado']==='PENDIENTE'):?><button class="btn" type="button" data-capacity-id="<?=(int)$r['id']?>" data-capacity-name="<?=htmlspecialchars($r['seccion_codigo'],ENT_QUOTES)?>" data-capacity-quantity="<?=(int)$r['cantidad_solicitada']?>">Revisar</button><?php else:?><?=htmlspecialchars((string)$r['observacion_resolucion'])?><?php endif;?></td></tr><?php endforeach;?>
<?php if(!$requests):?><tr><td colspan="7">No hay solicitudes registradas.</td></tr><?php endif;?></tbody></table></div></section>
<div id="capacityReview" hidden style="position:fixed;inset:0;background:#0009;z-index:9999;align-items:center;justify-content:center;padding:1rem" role="dialog" aria-modal="true" aria-labelledby="reviewTitle"><div class="card" style="width:min(100%,540px)"><h2 id="reviewTitle">Resolver solicitud</h2><p id="reviewDetails"></p><form method="post" action="<?=$u?>/admin/tic/cupos/resolver"><input type="hidden" name="_csrf" value="<?=htmlspecialchars(\App\Core\Csrf::token())?>"><input type="hidden" name="id" id="reviewId"><label>Observación de resolución<textarea name="observacion" minlength="5" required></textarea></label><div style="display:flex;gap:.5rem;flex-wrap:wrap"><button class="btn" name="decision" value="APROBAR">Aprobar</button><button class="btn" name="decision" value="RECHAZAR">Rechazar</button><button class="btn" type="button" id="reviewClose">Cancelar</button></div></form></div></div>
<script>const rev=document.getElementById('capacityReview');function closeReview(){rev.hidden=true;rev.style.display='none'}document.querySelectorAll('[data-capacity-id]').forEach(b=>b.addEventListener('click',()=>{document.getElementById('reviewId').value=b.dataset.capacityId;document.getElementById('reviewDetails').textContent=b.dataset.capacityName+' · '+b.dataset.capacityQuantity+' cupos adicionales';rev.hidden=false;rev.style.display='flex'}));document.getElementById('reviewClose').addEventListener('click',closeReview);rev.addEventListener('click',e=>{if(e.target===rev)closeReview()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeReview()});</script>

<section class="card"><h2>Solicitudes por cohorte académica</h2><p>Las solicitudes pendientes de esta sección requieren resolución de Coordinación TICs.</p><div class="table-scroll"><table><thead><tr><th>Carrera y nivel</th><th>Paralelo</th><th>Adicionales</th><th>Estado</th><th>Motivo</th><th>Acción</th></tr></thead><tbody><?php foreach(($cohortRequests??[]) as $r):?><tr><td><?=htmlspecialchars($r['carrera_nombre'].' · '.$r['nivel_nombre'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['paralelo'],ENT_QUOTES,'UTF-8')?></td><td><?=(int)$r['cantidad_solicitada']?></td><td><?=htmlspecialchars($r['estado'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['motivo'],ENT_QUOTES,'UTF-8')?></td><td><?php if($r['estado']==='PENDIENTE'):?><button class="btn" type="button" data-cohort-review data-id="<?=(int)$r['id']?>" data-name="<?=htmlspecialchars($r['carrera_nombre'].' · '.$r['nivel_nombre'],ENT_QUOTES,'UTF-8')?>" data-qty="<?=(int)$r['cantidad_solicitada']?>">Revisar</button><?php else:?><?=htmlspecialchars((string)$r['observacion_resolucion'],ENT_QUOTES,'UTF-8')?><?php endif;?></td></tr><?php endforeach;?><?php if(empty($cohortRequests)):?><tr><td colspan="6">No hay solicitudes por cohorte.</td></tr><?php endif;?></tbody></table></div></section>
<div id="cohortReviewModal" hidden style="position:fixed;inset:0;background:#0009;z-index:9999;align-items:center;justify-content:center;padding:1rem" role="dialog" aria-modal="true" aria-labelledby="cohortReviewTitle"><div class="card" style="width:min(100%,540px)"><h2 id="cohortReviewTitle">Resolver ampliación por cohorte</h2><p id="cohortReviewLabel"></p><form method="post" action="<?=$u?>/admin/tic/cupos/resolver-cohorte"><input type="hidden" name="_csrf" value="<?=htmlspecialchars(\App\Core\Csrf::token(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="id" id="cohortReviewId"><label>Observación<textarea name="observacion" minlength="5" required></textarea></label><div style="display:flex;gap:.5rem"><button class="btn" name="decision" value="APROBAR">Aprobar</button><button class="btn" name="decision" value="RECHAZAR">Rechazar</button><button class="btn" type="button" id="cohortReviewClose">Cancelar</button></div></form></div></div>
<script>(function(){const m=document.getElementById('cohortReviewModal');const close=()=>{m.hidden=true;m.style.display='none'};document.querySelectorAll('[data-cohort-review]').forEach(b=>b.addEventListener('click',()=>{document.getElementById('cohortReviewId').value=b.dataset.id;document.getElementById('cohortReviewLabel').textContent=b.dataset.name+' · '+b.dataset.qty+' cupos adicionales';m.hidden=false;m.style.display='flex'}));document.getElementById('cohortReviewClose').addEventListener('click',close);m.addEventListener('click',e=>{if(e.target===m)close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!m.hidden)close()})})();</script>
